def chunk_lazy(text, size, overlap):
    words = text.split()
    step = size - overlap
    i = 0
    while i < len(words):
        yield " ".join(words[i:i + size])
        if i + size >= len(words):
            break
        i += step

def chunk_with_meta(text, size, overlap):
    words = text.split()
    step = size - overlap
    chunks = []
    i = 0
    while i < len(words):
        end = min(i + size, len(words))
        chunks.append({
            "text": " ".join(words[i:end]),
            "start": i,
            "end": end,
            "index": len(chunks),
        })
        if i + size >= len(words):
            break
        i += step
    return chunks

