def split_sentences(text, max_tokens):
    chunks = []
    current = []
    current_tokens = 0
    for s in text.split(". "):
        t = count_tokens(s)
        if current and current_tokens + t > max_tokens:
            chunks.append(". ".join(current))
            current = [s]
            current_tokens = t
        else:
            current.append(s)
            current_tokens += t
    if current:
        chunks.append(". ".join(current))
    return chunks

def safe_chunk(text, size, overlap):
    if overlap >= size:
        raise ValueError("overlap must be smaller than size")
    words = text.split()
    if not words:
        return []
    if len(words) <= size:
        return [" ".join(words)]
    step = size - overlap
    chunks = []
    i = 0
    while i < len(words):
        chunks.append(" ".join(words[i:i + size]))
        if i + size >= len(words):
            break
        i += step
    return chunks

