def chunk_no_crumbs(text, size):
    words = text.split()
    if not words:
        return []
    chunks = []
    for i in range(0, len(words), size):
        chunks.append(" ".join(words[i:i + size]))
    if len(chunks) > 1 and len(chunks[-1].split()) < size * 0.25:
        chunks[-2] = chunks[-2] + " " + chunks[-1]
        chunks.pop()
    return chunks

