def pack_sentences(text, max_tokens):
    if not text:
        return []
    chunks = []
    current = []
    current_tokens = 0
    for s in text.split(". "):
        t = count_tokens(s)
        if t > max_tokens:
            if current:
                chunks.append(". ".join(current))
                current = []
                current_tokens = 0
            words = s.split()
            for i in range(0, len(words), max_tokens):
                chunks.append(" ".join(words[i:i + max_tokens]))
        elif current_tokens + t > max_tokens:
            chunks.append(". ".join(current))
            current = [s]
            current_tokens = t
        else:
            current.append(s)
            current_tokens += t
    if current:
        chunks.append(". ".join(current))
    return chunks

