def search_no_duplicates(query, corpus, k, dup_threshold):
    if not corpus:
        return []
    q = embed(query)
    ranked = [(t, float(np.dot(embed(t), q))) for t in corpus]
    ranked.sort(key=lambda p: -p[1])
    chosen = []
    for text, score in ranked:
        v = embed(text)
        duplicate = False
        for ct, _cs in chosen:
            if float(np.dot(v, embed(ct))) > dup_threshold:
                duplicate = True
                break
        if not duplicate:
            chosen.append((text, score))
        if len(chosen) == k:
            break
    return chosen

